mapper.insert:
/*
     SQL ID : PopupNtcDAO.insertPopupNtc
     설  명 : 팝업공지 등록
 */
INSERT INTO TB_LMS_POPUP_NTC (
      POPUP_NTC_ID
    , ORG_ID
    , POPUP_NTC_TTL
    , POPUP_NTC_CTS
    , POPUP_NTC_SDTTM
    , POPUP_NTC_EDTTM
    , POPUP_NTC_TDSTOP_USEYN
    , USEYN
    , POPUP_NTC_TRGT
    , POPUP_PNTTIME_GBNCD
    , RGTR_ID
    , REG_DTTM
) VALUES (
      #{popupNtcId}
    , #{orgId}
    , #{popupNtcTtl}
    , #{popupNtcCts}
    , #{popupNtcSdttm}
    , #{popupNtcEdttm}
    , #{popupNtcTdstopUseyn}
    , 'Y'
    , #{popupNtcTrgt}
    , #{popupPnttimeGbncd}
    , #{rgtrId}
    , FN_DTTM()
)

/*
     SQL ID : PopupNtcDAO.insertPopupNtcPstnSz
     설  명 : 팝업공지 위치크기 등록
 */
INSERT INTO TB_LMS_POPUP_NTC_PSTN_SIZE (
      POPUP_NTC_ID
    , POPUP_WIN_WDTHSZ
    , POPUP_WIN_HGHT
    , POPUP_WIN_XCRD
    , POPUP_WIN_YCRD
    , RGTR_ID
    , REG_DTTM
) VALUES (
      #{popupNtcId}
    , #{popupWinWdthsz}
    , #{popupWinHght}
    , #{popupWinXcrd}
    , #{popupWinYcrd}
    , #{rgtrId}
    , FN_DTTM()
)

mapper.update:
/*
     SQL ID : PopupNtcDAO.updatePopupNtc
     설  명 : 팝업공지 수정
 */
UPDATE TB_LMS_POPUP_NTC
SET POPUP_NTC_TTL = #{popupNtcTtl}
  , POPUP_NTC_CTS = #{popupNtcCts}
  , POPUP_NTC_SDTTM = #{popupNtcSdttm}
  , POPUP_NTC_EDTTM = #{popupNtcEdttm}
  , POPUP_NTC_TDSTOP_USEYN = #{popupNtcTdstopUseyn}
  , POPUP_NTC_TRGT = #{popupNtcTrgt}
  , POPUP_PNTTIME_GBNCD = #{popupPnttimeGbncd}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE POPUP_NTC_ID = #{popupNtcId}

/*
     SQL ID : PopupNtcDAO.updatePopupNtcPstnSz
     설  명 : 팝업공지 위치크기 수정
 */
UPDATE TB_LMS_POPUP_NTC_PSTN_SIZE
SET POPUP_WIN_WDTHSZ = #{popupWinWdthsz}
  , POPUP_WIN_HGHT = #{popupWinHght}
  , POPUP_WIN_XCRD = #{popupWinXcrd}
  , POPUP_WIN_YCRD = #{popupWinYcrd}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE POPUP_NTC_ID = #{popupNtcId}

/*
     SQL ID : PopupNtcDAO.updatePopupNtcUseyn
     설  명 : 팝업공지 전시여부 수정
 */
UPDATE TB_LMS_POPUP_NTC
SET USEYN = #{useyn}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE POPUP_NTC_ID = #{popupNtcId}

mapper.delete:
/*
     SQL ID : PopupNtcDAO.deletePopupNtcPstnSz
